36	/**
37	 * 雨季溢流证据与双口径统计服务（cems-02 新增，合成规则，不用于生产）。
38	 * 溢流证据独立留痕：原排放浓度读数、超标链与限排令记录不因溢流标记而改变；
39	 * 溢流不取消已生效限排令，也不减轻原超标判定。
40	 * 所有写路径（许可版本、小时上报、雨量更正、日结冻结）先取排口行锁，
41	 * 业务、版本号与幂等结果在同一事务内提交；失败整体回滚、不占幂等键。
42	 */
43	@Service
44	public class OverflowService {
45	
46	    /** 日结小时数：UTC 日固定 24 个整点槽位。 */
47	    static final int DAY_SLOTS = 24;
48	
49	    private final OverflowRepository repo;
50	    private final CemsRepository cemsRepo;
51	    private final CemsClock clock;
52	    private final IdempotencySupport idem;
53	
54	    public OverflowService(OverflowRepository repo, CemsRepository cemsRepo,
55	                           CemsClock clock, IdempotencySupport idem) {
56	        this.repo = repo;
57	        this.cemsRepo = cemsRepo;
58	        this.clock = clock;
59	        this.idem = idem;
60	    }
61	
62	    // ---------------- 溢流许可版本（expectedVersion 乐观并发） ----------------
63	
64	    @Transactional
65	    public PermitView upsertPermit(PermitUpsertRequest req) {
66	        Map<String, Object> fields = new LinkedHashMap<>();
67	        fields.put("outletCode", req.outletCode());
68	        fields.put("expectedVersion", req.expectedVersion());
69	        fields.put("windowStartUtc", req.windowStartUtc() == null ? null : req.windowStartUtc().toString());
70	        fields.put("windowEndUtc", req.windowEndUtc() == null ? null : req.windowEndUtc().toString());
71	        fields.put("minRainfallMm", req.minRainfallMm());
72	        fields.put("maxConsecutiveHours", req.maxConsecutiveHours());
73	        return replayable(req.requestId(), "OVERFLOW_PERMIT", fields, PermitView.class,
74	                () -> doUpsertPermit(req));
75	    }
76	
77	    private PermitView doUpsertPermit(PermitUpsertRequest req) {
78	        String code = requireText(req.outletCode(), "outletCode");
79	        loadOutlet(code);
80	        if (req.expectedVersion() == null) {
81	            throw new IllegalArgumentException("expectedVersion 不能为空（无许可时传 0）");
82	        }
83	        if (req.expectedVersion() < 0) {
84	            throw new IllegalArgumentException("expectedVersion 不能为负数");
85	        }
86	        if (req.windowStartUtc() == null || req.windowEndUtc() == null) {
87	            throw new IllegalArgumentException("windowStartUtc/windowEndUtc 不能为空");
88	        }
89	        if (!req.windowEndUtc().isAfter(req.windowStartUtc())) {
90	            throw new IllegalArgumentException("windowEndUtc 必须晚于 windowStartUtc（UTC 半开窗口）");
91	        }
92	        requireNonNullNonNegative(req.minRainfallMm(), "minRainfallMm");
93	        if (req.maxConsecutiveHours() == null || req.maxConsecutiveHours() < 1) {
94	            throw new IllegalArgumentException("maxConsecutiveHours 必须为正整数");
95	        }
96	        cemsRepo.lockOutlet(code);
97	        Map<String, Object> latest = repo.findLatestPermit(code);
98	        int current = latest == null ? 0 : ((Number) latest.get("version")).intValue();
99	        if (req.expectedVersion() != current) {
100	            throw new ConflictException("溢流许可版本不匹配: expectedVersion=" + req.expectedVersion()
101	                    + " 当前版本=" + current);
102	        }
103	        int newVersion = current + 1;
104	        LocalDateTime now = clock.now();
105	        repo.supersedeActivePermits(code);
106	        try {
107	            repo.insertPermit(code, newVersion, toUtcLdt(req.windowStartUtc()), toUtcLdt(req.windowEndUtc()),
108	                    req.minRainfallMm(), req.maxConsecutiveHours(), now);
109	        } catch (DuplicateKeyException e) {
110	            throw new ConflictException("溢流许可版本 " + newVersion + " 已存在（并发新增冲突）: " + code);
111	        }
112	        cemsRepo.insertEvent(code, "OVERFLOW_PERMIT", now, false,
113	                "version=" + newVersion + " window=[" + req.windowStartUtc() + "," + req.windowEndUtc() + ")"
114	                        + " minRainfallMm=" + req.minRainfallMm()
115	                        + " maxConsecutiveHours=" + req.maxConsecutiveHours());
116	        // 许可边界变化后按既有小时数据重建分段（跨许可必须断段）。
117	        rebuildSegments(code);
118	        return toPermitView(repo.findLatestPermit(code));
119	    }
120	
121	    // ---------------- 小时数据上报与合规溢流标记 ----------------
122	
123	    @Transactional
124	    public HourReportResult reportHours(HourReportRequest req) {
125	        Map<String, Object> fields = new LinkedHashMap<>();
126	        fields.put("outletCode", req.outletCode());
127	        fields.put("hours", canonicalHours(req.hours()));
128	        return replayable(req.requestId(), "OVERFLOW_HOURS", fields, HourReportResult.class,
129	                () -> doReportHours(req));
130	    }
131	
132	    private HourReportResult doReportHours(HourReportRequest req) {
133	        String code = requireText(req.outletCode(), "outletCode");
134	        loadOutlet(code);
135	        if (req.hours() == null || req.hours().isEmpty()) {
136	            throw new IllegalArgumentException("hours 不能为空集合");
137	        }
138	        Map<String, Boolean> seen = new LinkedHashMap<>();
139	        for (OverflowHourItem item : req.hours()) {
140	            validateHourItem(item);
141	            String key = item.hourUtc().toString();
142	            if (seen.put(key, Boolean.TRUE) != null) {
143	                throw new IllegalArgumentException("hours 内存在重复 UTC 整点: " + key);
144	            }
145	        }
146	        List<OverflowHourItem> items = new ArrayList<>(req.hours());
147	        items.sort(Comparator.comparing(OverflowHourItem::hourUtc));
148	        cemsRepo.lockOutlet(code);
149	        LocalDateTime now = clock.now();
150	        repo.ensureCounter(code, now);
151	        int reported = 0;
152	        int deduplicated = 0;
153	        List<HourMarkView> views = new ArrayList<>();
154	        for (OverflowHourItem item : items) {
155	            LocalDateTime hourUtc = toUtcLdt(item.hourUtc());
156	            Map<String, Object> existing = repo.findHour(code, hourUtc);
157	            if (existing != null) {
158	                // 排口＋整点去重：同参去重，异参 409；雨量更正须走更正入口。
159	                if (sameHourData(existing, item)) {
160	                    views.add(toHourMarkView(existing, true));
161	                    deduplicated++;
162	                    continue;
163	                }
164	                throw new ConflictException("排口＋UTC 整点小时数据已存在且内容不同: " + code + " " + item.hourUtc());
165	            }
166	            MarkDecision decision = evaluateNewHour(code, item, hourUtc);
167	            repo.insertHour(code, hourUtc, item.rainfallMm(), item.overflowFlag(), item.avgValue(),
168	                    decision.markStatus(), decision.permitVersion(), now);
169	            reported++;
170	            views.add(new HourMarkView(item.hourUtc(), decision.markStatus(), decision.permitVersion(),
171	                    item.rainfallMm(), item.overflowFlag(), item.avgValue(), false));
172	        }
173	        rebuildSegments(code);
174	        cemsRepo.insertEvent(code, "OVERFLOW_HOURS", now, false,
175	                "reported=" + reported + " deduplicated=" + deduplicated);
176	        return new HourReportResult(req.requestId(), code, reported, deduplicated, views);
177	    }
178	
179	    /**
180	     * 新小时标记判定：仅在许可有效、雨量≥门槛（恰等合法）且该小时完整落窗时可标合规溢流；
181	     * 缺雨量只能待核（不当零也不豁免）；其余溢流标记请求属业务拒绝（422）。
182	     */
183	    private MarkDecision evaluateNewHour(String code, OverflowHourItem item, LocalDateTime hourUtc) {
184	        if (!item.overflowFlag()) {
185	            return new MarkDecision("NORMAL", null);
186	        }
187	        if (item.rainfallMm() == null) {
188	            return new MarkDecision("PENDING", null);
189	        }
190	        Map<String, Object> permit = repo.findActivePermit(code);
191	        if (permit == null) {
192	            throw new BusinessException("无现行溢流许可，不能标记合规溢流: " + code);
193	        }
194	        LocalDateTime windowStart = lt(permit.get("window_start_utc"));
195	        LocalDateTime windowEnd = lt(permit.get("window_end_utc"));
196	        if (hourUtc.isBefore(windowStart) || hourUtc.plusHours(1).isAfter(windowEnd)) {
197	            throw new BusinessException("该小时未完整落入许可 UTC 半开窗口 [" + windowStart + "," + windowEnd
198	                    + "): " + hourUtc);
199	        }
200	        BigDecimal minRainfall = bd(permit.get("min_rainfall_mm"));
201	        if (item.rainfallMm().compareTo(minRainfall) < 0) {
202	            throw new BusinessException("小时雨量 " + item.rainfallMm() + "mm 低于许可门槛 "
203	                    + minRainfall + "mm，不能标记合规溢流");
204	        }
205	        return new MarkDecision("COMPLIANT", ((Number) permit.get("version")).intValue());
206	    }
207	
208	    // ---------------- 雨量更正（复核前重算 / 复核后独立调差） ----------------
209	
210	    @Transactional
211	    public RainfallCorrectionResult correctRainfall(RainfallCorrectionRequest req) {
212	        Map<String, Object> fields = new LinkedHashMap<>();
213	        fields.put("outletCode", req.outletCode());
214	        fields.put("hourUtc", req.hourUtc() == null ? null : req.hourUtc().toString());
215	        fields.put("rainfallMm", req.rainfallMm());
216	        fields.put("expectedVersion", req.expectedVersion());
217	        return replayable(req.requestId(), "OVERFLOW_CORRECTION", fields,
218	                RainfallCorrectionResult.class, () -> doCorrectRainfall(req));
219	    }
220	
221	    private RainfallCorrectionResult doCorrectRainfall(RainfallCorrectionRequest req) {
222	        String code = requireText(req.outletCode(), "outletCode");
223	        loadOutlet(code);
224	        if (req.hourUtc() == null) {
225	            throw new IllegalArgumentException("hourUtc 不能为空");
226	        }
227	        requireWholeHour(req.hourUtc(), "hourUtc");
228	        requireNonNullNonNegative(req.rainfallMm(), "rainfallMm");
229	        if (req.expectedVersion() == null) {
230	            throw new IllegalArgumentException("expectedVersion 不能为空");
231	        }
232	        cemsRepo.lockOutlet(code);
233	        LocalDateTime hourUtc = toUtcLdt(req.hourUtc());
234	        Map<String, Object> hour = repo.findHour(code, hourUtc);
235	        if (hour == null) {
236	            throw new NotFoundException("小时数据不存在: " + code + " " + req.hourUtc());
237	        }
238	        Integer currentVersion = repo.findRainfallVersion(code);
239	        if (currentVersion == null || req.expectedVersion() != currentVersion) {
240	            throw new ConflictException("雨量版本不匹配: expectedVersion=" + req.expectedVersion()
241	                    + " 当前版本=" + currentVersion);
242	        }
243	        LocalDateTime now = clock.now();
244	        if (repo.bumpRainfallVersion(code, currentVersion, now) == 0) {
245	            throw new ConflictException("雨量版本已变化，更正未受理: " + code);
246	        }
247	        int newVersion = currentVersion + 1;
248	        LocalDate dayUtc = hourUtc.toLocalDate();
249	        BigDecimal oldRainfall = bd(hour.get("rainfall_mm"));
250	        if (repo.findReview(code, dayUtc) != null) {
251	            // 复核冻结后：只登记独立调差，不改日结快照，也不改已冻结小时的雨量与标记。
252	            repo.insertAdjustment(code, dayUtc, hourUtc, oldRainfall, req.rainfallMm(),
253	                    newVersion, req.requestId(), now);
254	            cemsRepo.insertEvent(code, "OVERFLOW_ADJUSTMENT", now, false,
255	                    "day=" + dayUtc + " hour=" + req.hourUtc() + " rainfall " + oldRainfall
256	                            + "->" + req.rainfallMm() + " rainfallVersion=" + newVersion);
257	            return new RainfallCorrectionResult(req.requestId(), code, req.hourUtc(), newVersion,
258	                    true, (String) hour.get("mark_status"), true);
259	        }
260	        // 复核冻结前：更正雨量并重算该小时标记与连续分段（同事务）。
261	        MarkDecision decision = reevaluateMark(code, bool(hour.get("overflow_flag")), req.rainfallMm(), hourUtc);
262	        repo.updateHourRainfallAndMark(code, hourUtc, req.rainfallMm(),
263	                decision.markStatus(), decision.permitVersion(), now);
264	        rebuildSegments(code);
265	        cemsRepo.insertEvent(code, "OVERFLOW_CORRECTION", now, false,
266	                "hour=" + req.hourUtc() + " rainfall " + oldRainfall + "->" + req.rainfallMm()
267	                        + " mark=" + decision.markStatus() + " rainfallVersion=" + newVersion);
268	        return new RainfallCorrectionResult(req.requestId(), code, req.hourUtc(), newVersion,
269	                false, decision.markStatus(), false);
270	    }
271	
272	    /** 复核前重算：按当前现行许可与更正后雨量重新判定；证据不足降级为 NORMAL（更正属数据维护，不拒绝）。 */
273	    private MarkDecision reevaluateMark(String code, boolean overflowFlag, BigDecimal rainfallMm,
274	                                        LocalDateTime hourUtc) {
275	        if (!overflowFlag) {
276	            return new MarkDecision("NORMAL", null);
277	        }
278	        Map<String, Object> permit = repo.findActivePermit(code);
279	        if (permit == null) {
280	            return new MarkDecision("NORMAL", null);
281	        }
282	        LocalDateTime windowStart = lt(permit.get("window_start_utc"));
283	        LocalDateTime windowEnd = lt(permit.get("window_end_utc"));
284	        if (hourUtc.isBefore(windowStart) || hourUtc.plusHours(1).isAfter(windowEnd)) {
285	            return new MarkDecision("NORMAL", null);
286	        }
287	        if (rainfallMm.compareTo(bd(permit.get("min_rainfall_mm"))) < 0) {
288	            return new MarkDecision("NORMAL", null);
289	        }
290	        return new MarkDecision("COMPLIANT", ((Number) permit.get("version")).intValue());
291	    }
292	
293	    // ---------------- 日结复核冻结（双口径快照） ----------------
294	
295	    @Transactional
296	    public ReviewView freezeReview(ReviewFreezeRequest req) {
297	        Map<String, Object> fields = new LinkedHashMap<>();
298	        fields.put("outletCode", req.outletCode());
299	        fields.put("dayUtc", req.dayUtc() == null ? null : req.dayUtc().toString());
300	        return replayable(req.requestId(), "OVERFLOW_REVIEW", fields, ReviewView.class,
301	                () -> doFreezeReview(req));
302	    }
303	
304	    private ReviewView doFreezeReview(ReviewFreezeRequest req) {
305	        String code = requireText(req.outletCode(), "outletCode");
306	        loadOutlet(code);
307	        if (req.dayUtc() == null) {
308	            throw new IllegalArgumentException("dayUtc 不能为空");
309	        }
310	        // 与小时标记写路径竞争同一排口行锁：冻结到的双口径结果必然来自同一一致快照。
311	        cemsRepo.lockOutlet(code);
312	        if (repo.findReview(code, req.dayUtc()) != null) {
313	            throw new ConflictException("该 UTC 日已复核冻结，不能重复冻结: " + code + " " + req.dayUtc());
314	        }
315	        LocalDateTime dayStart = toUtcLdt(req.dayUtc().atStartOfDay(ZoneOffset.UTC).toInstant());
316	        List<Map<String, Object>> hours = repo.findHoursBetween(code, dayStart, dayStart.plusDays(1));
317	        for (Map<String, Object> h : hours) {
318	            if ("PENDING".equals(h.get("mark_status"))) {
319	                throw new BusinessException("存在待核小时（缺雨量）" + lt(h.get("hour_utc"))
320	                        + "，不能复核冻结；缺雨量不能当零或直接豁免");
321	            }
322	        }
323	        LocalDateTime now = clock.now();
324	        Map<String, Object> permit = repo.findActivePermit(code);
325	        Integer permitVersion = permit == null ? null : ((Number) permit.get("version")).intValue();
326	        Integer rainfallVersion = repo.findRainfallVersion(code);
327	        AveragePair averages = computeAverages(hours);
328	        int missingCount = DAY_SLOTS - hours.size();
329	        try {
330	            repo.insertReview(code, req.dayUtc(), permitVersion,
331	                    rainfallVersion == null ? 0 : rainfallVersion,
332	                    averages.normalAvg(), averages.normalCount(),
333	                    averages.allAvg(), averages.allCount(), missingCount, req.requestId(), now);
334	        } catch (DuplicateKeyException e) {
335	            throw new ConflictException("该 UTC 日已复核冻结（并发冻结唯一受理）: " + code + " " + req.dayUtc());
336	        }
337	        cemsRepo.insertEvent(code, "OVERFLOW_REVIEW", now, false,
338	                "day=" + req.dayUtc() + " permitVersion=" + permitVersion
339	                        + " rainfallVersion=" + rainfallVersion
340	                        + " normal=" + averages.normalAvg() + "/" + averages.normalCount()
341	                        + " all=" + averages.allAvg() + "/" + averages.allCount());
342	        return toReviewView(repo.findReview(code, req.dayUtc()));
343	    }
344	
345	    // ---------------- 双口径均值查询 ----------------
346	
347	    /**
348	     * 双口径均值：正常排放口径仅排除证据齐全的合规溢流小时（待核不排除），全部排放口径不排除；
349	     * 分母与缺点（无记录整点）明示；空集合均值为 null（无结果而非零）。
350	     */
351	    @Transactional(readOnly = true)
352	    public AveragesView averages(String code, Instant fromUtc, Instant toUtc) {
353	        requireText(code, "outletCode");
354	        loadOutlet(code);
355	        if (fromUtc == null || toUtc == null) {
356	            throw new IllegalArgumentException("from/to 不能为空（UTC 精确时刻，如 2026-09-26T00:00:00Z）");
357	        }
358	        requireWholeHour(fromUtc, "from");
359	        requireWholeHour(toUtc, "to");
360	        if (!toUtc.isAfter(fromUtc)) {
361	            throw new IllegalArgumentException("to 必须晚于 from（UTC 半开区间）");
362	        }
363	        LocalDateTime from = toUtcLdt(fromUtc);
364	        LocalDateTime to = toUtcLdt(toUtc);
365	        Map<String, Map<String, Object>> byHour = new LinkedHashMap<>();
366	        for (Map<String, Object> h : repo.findHoursBetween(code, from, to)) {
367	            byHour.put(lt(h.get("hour_utc")).toString(), h);
368	        }
369	        long totalSlots = java.time.Duration.between(from, to).toHours();
370	        List<Instant> missingHours = new ArrayList<>();
371	        List<Map<String, Object>> reported = new ArrayList<>();
372	        for (long i = 0; i < totalSlots; i++) {
373	            LocalDateTime slot = from.plusHours(i);
374	            Map<String, Object> h = byHour.get(slot.toString());
375	            if (h == null) {
376	                missingHours.add(slot.toInstant(ZoneOffset.UTC));
377	            } else {
378	                reported.add(h);
379	            }
380	        }
381	        AveragePair averages = computeAverages(reported);
382	        int pendingCount = (int) reported.stream()
383	                .filter(h -> "PENDING".equals(h.get("mark_status"))).count();
384	        return new AveragesView(code, fromUtc, toUtc, totalSlots, reported.size(),
385	                missingHours.size(), pendingCount,
386	                averages.normalAvg(), averages.normalCount(),
387	                averages.allAvg(), averages.allCount(), missingHours);
388	    }
389	
390	    /** 双口径统计：normal 仅排除 COMPLIANT；空集合均值为 null。 */
391	    private AveragePair computeAverages(List<Map<String, Object>> hours) {
392	        BigDecimal allSum = BigDecimal.ZERO;
393	        int allCount = 0;
394	        BigDecimal normalSum = BigDecimal.ZERO;
395	        int normalCount = 0;
396	        for (Map<String, Object> h : hours) {
397	            BigDecimal value = bd(h.get("avg_value"));
398	            allSum = allSum.add(value);
399	            allCount++;
400	            if (!"COMPLIANT".equals(h.get("mark_status"))) {
401	                normalSum = normalSum.add(value);
402	                normalCount++;
403	            }
404	        }
405	        return new AveragePair(
406	                normalCount == 0 ? null : normalSum.divide(BigDecimal.valueOf(normalCount), 4,
407	                        RoundingMode.HALF_UP),
408	                normalCount,
409	                allCount == 0 ? null : allSum.divide(BigDecimal.valueOf(allCount), 4,
410	                        RoundingMode.HALF_UP),
411	                allCount);
412	    }
413	
414	    // ---------------- 连续分段与专项异常 ----------------
415	
416	    /**
417	     * 连续合规溢流分段：相邻 UTC 整点且许可版本相同才连续；跨许可或出现缺点（无记录/待核/非合规）
418	     * 必须断段；段长严格超过许可最长连续小时数即登记专项异常。
419	     */
420	    private void rebuildSegments(String code) {
421	        Map<Integer, Map<String, Object>> permitsByVersion = new LinkedHashMap<>();
422	        for (Map<String, Object> p : repo.findPermits(code)) {
423	            permitsByVersion.put(((Number) p.get("version")).intValue(), p);
424	        }
425	        repo.deleteAnomalies(code);
426	        LocalDateTime now = clock.now();
427	        List<Map<String, Object>> run = new ArrayList<>();
428	        Map<String, Object> prevCompliant = null;
429	        for (Map<String, Object> h : repo.findHours(code)) {
430	            if (!"COMPLIANT".equals(h.get("mark_status"))) {
431	                flushSegment(code, run, permitsByVersion, now);
432	                run = new ArrayList<>();
433	                prevCompliant = null;
434	                continue;
435	            }
436	            boolean adjacent = prevCompliant != null
437	                    && lt(h.get("hour_utc")).equals(lt(prevCompliant.get("hour_utc")).plusHours(1))
438	                    && Objects.equals(permitVersionOf(h), permitVersionOf(prevCompliant));
439	            if (!adjacent) {
440	                flushSegment(code, run, permitsByVersion, now);
441	                run = new ArrayList<>();
442	            }
443	            run.add(h);
444	            prevCompliant = h;
445	        }
446	        flushSegment(code, run, permitsByVersion, now);
447	    }
448	
449	    private void flushSegment(String code, List<Map<String, Object>> run,
450	                              Map<Integer, Map<String, Object>> permitsByVersion, LocalDateTime now) {
451	        if (run.isEmpty()) {
452	            return;
453	        }
454	        Integer permitVersion = permitVersionOf(run.get(0));
455	        Map<String, Object> permit = permitVersion == null ? null : permitsByVersion.get(permitVersion);
456	        int maxAllowed = permit == null ? 0
457	                : ((Number) permit.get("max_consecutive_hours")).intValue();
458	        if (run.size() > maxAllowed) {
459	            LocalDateTime start = lt(run.get(0).get("hour_utc"));
460	            LocalDateTime end = lt(run.get(run.size() - 1).get("hour_utc")).plusHours(1);
461	            repo.insertAnomaly(code, start, end, run.size(), maxAllowed,
462	                    permitVersion == null ? 0 : permitVersion,
463	                    "连续合规溢流 " + run.size() + " 小时超过许可（版本 " + permitVersion
464	                            + "）最长连续 " + maxAllowed + " 小时", now);
465	        }
466	    }
467	
468	    // ---------------- 查询 ----------------
469	
470	    @Transactional(readOnly = true)
471	    public PermitView getCurrentPermit(String code) {
472	        requireText(code, "outletCode");
473	        loadOutlet(code);
474	        Map<String, Object> permit = repo.findActivePermit(code);
475	        if (permit == null) {
476	            throw new NotFoundException("排口无现行溢流许可: " + code);
477	        }
478	        return toPermitView(permit);
479	    }
480	
481	    @Transactional(readOnly = true)
482	    public ReviewView getReview(String code, LocalDate dayUtc) {
483	        requireText(code, "outletCode");
484	        loadOutlet(code);
485	        Map<String, Object> review = repo.findReview(code, dayUtc);
486	        if (review == null) {
487	            throw new NotFoundException("日结复核快照不存在: " + code + " " + dayUtc);
488	        }
489	        return toReviewView(review);
490	    }
491	
492	    @Transactional(readOnly = true)
493	    public List<AnomalyView> listAnomalies(String code) {
494	        requireText(code, "outletCode");
495	        loadOutlet(code);
496	        List<AnomalyView> views = new ArrayList<>();
497	        for (Map<String, Object> a : repo.findAnomalies(code)) {
498	            views.add(new AnomalyView(code,
499	                    lt(a.get("segment_start_utc")).toInstant(ZoneOffset.UTC),
500	                    lt(a.get("segment_end_utc")).toInstant(ZoneOffset.UTC),
501	                    ((Number) a.get("hour_count")).intValue(),
502	                    ((Number) a.get("max_allowed")).intValue(),
503	                    ((Number) a.get("permit_version")).intValue(),
504	                    (String) a.get("reason"), (String) a.get("status")));
505	        }
506	        return views;
507	    }
508	
509	    // ---------------- 幂等支撑（与 CemsService 同构：同键同参回放、异参 409、失败不占键） ----------------
510	
511	    private <T> T replayable(String requestId, String requestType, Map<String, Object> fields,
512	                             Class<T> resultType, Supplier<T> action) {
513	        String rid = requireText(requestId, "requestId");
514	        String fingerprint = idem.fingerprint(rid, fields);
515	        Map<String, Object> existing = cemsRepo.findIdempotent(rid);
516	        if (existing != null) {
517	            return replayOrConflict(rid, fingerprint, existing, resultType);
518	        }
519	        while (true) {
520	            if (cemsRepo.insertIdempotent(rid, requestType, fingerprint, "", clock.now())) {
521	                T result = action.get();
522	                cemsRepo.updateIdempotentResult(rid, idem.toJson(result));
523	                return result;
524	            }
525	            Map<String, Object> raced = waitForIdempotentResult(rid);
526	            if (raced != null) {
527	                return replayOrConflict(rid, fingerprint, raced, resultType);
528	            }
529	        }
530	    }
531	
532	    private <T> T replayOrConflict(String rid, String fingerprint, Map<String, Object> row,
533	                                   Class<T> resultType) {
534	        if (!fingerprint.equals(row.get("fingerprint"))) {
535	            throw new ConflictException("requestId=" + rid + " 请求参数与首次调用不一致（409 幂等冲突）");
536	        }
537	        return idem.fromJson((String) row.get("result_json"), resultType);
538	    }
539	
540	    private Map<String, Object> waitForIdempotentResult(String rid) {
541	        long deadlineMillis = System.currentTimeMillis() + 15_000L;
542	        while (true) {
543	            Map<String, Object> row = cemsRepo.findIdempotent(rid);
544	            if (row == null) {
545	                return null;
546	            }
547	            if (!"".equals(row.get("result_json"))) {
548	                return row;
549	            }
550	            if (System.currentTimeMillis() >= deadlineMillis) {
551	                throw new ConflictException("requestId=" + rid + " 并发请求等待首次结果超时");
552	            }
553	            try {
554	                Thread.sleep(20L);
555	            } catch (InterruptedException e) {
556	                Thread.currentThread().interrupt();
557	                throw new ConflictException("并发幂等等待被中断");
558	            }
559	        }
560	    }
561	
562	    // ---------------- 公共辅助 ----------------
563	
564	    private Map<String, Object> loadOutlet(String code) {
565	        Map<String, Object> outlet = cemsRepo.findOutlet(code);
566	        if (outlet == null) {
567	            throw new NotFoundException("排口不存在: " + code);
568	        }
569	        return outlet;
570	    }
571	
572	    private void validateHourItem(OverflowHourItem item) {
573	        if (item == null) {
574	            throw new IllegalArgumentException("hours 内不能包含空项");
575	        }
576	        if (item.hourUtc() == null) {
577	            throw new IllegalArgumentException("hourUtc 不能为空");
578	        }
579	        requireWholeHour(item.hourUtc(), "hourUtc");
580	        if (item.overflowFlag() == null) {
581	            throw new IllegalArgumentException("overflowFlag 不能为空");
582	        }
583	        requireNonNullNonNegative(item.avgValue(), "avgValue");
584	        if (item.rainfallMm() != null && item.rainfallMm().signum() < 0) {
585	            throw new IllegalArgumentException("rainfallMm 不能为负数");
586	        }
587	    }
588	
589	    private static void requireWholeHour(Instant instant, String field) {
590	        if (instant.getNano() != 0 || instant.getEpochSecond() % 3600 != 0) {
591	            throw new IllegalArgumentException(field + " 必须为 UTC 整点（分秒为 0）: " + instant);
592	        }
593	    }
594	
595	    private static boolean sameHourData(Map<String, Object> existing, OverflowHourItem item) {
596	        BigDecimal existingRainfall = bd(existing.get("rainfall_mm"));
597	        boolean sameRainfall = existingRainfall == null ? item.rainfallMm() == null
598	                : item.rainfallMm() != null && existingRainfall.compareTo(item.rainfallMm()) == 0;
599	        return sameRainfall
600	                && bool(existing.get("overflow_flag")) == item.overflowFlag()
601	                && bd(existing.get("avg_value")).compareTo(item.avgValue()) == 0;
602	    }
603	
604	    /** 幂等指纹用的小时集合规范化：按 UTC 整点排序，时刻用 ISO 文本，数值原样（JSON 结构化无歧义）。 */
605	    private static List<Map<String, Object>> canonicalHours(List<OverflowHourItem> hours) {
606	        if (hours == null) {
607	            return null;
608	        }
609	        List<Map<String, Object>> list = new ArrayList<>();
610	        for (OverflowHourItem item : hours) {
611	            if (item == null) {
612	                list.add(null);
613	                continue;
614	            }
615	            Map<String, Object> m = new TreeMap<>();
616	            m.put("hourUtc", item.hourUtc() == null ? null : item.hourUtc().toString());
617	            m.put("rainfallMm", item.rainfallMm());
618	            m.put("overflowFlag", item.overflowFlag());
619	            m.put("avgValue", item.avgValue());
620	            list.add(m);
621	        }
622	        list.sort(Comparator.comparing(m -> m == null ? "" : String.valueOf(m.get("hourUtc"))));
623	        return list;
624	    }
625	
626	    private static Integer permitVersionOf(Map<String, Object> hourRow) {
627	        Object v = hourRow.get("permit_version");
628	        return v == null ? null : ((Number) v).intValue();
629	    }
630	
631	    private static LocalDateTime toUtcLdt(Instant instant) {
632	        return LocalDateTime.ofInstant(instant, ZoneOffset.UTC);
633	    }
634	
635	    private static BigDecimal bd(Object value) {
636	        if (value == null) {
637	            return null;
638	        }
639	        return value instanceof BigDecimal b ? b : new BigDecimal(value.toString());
640	    }
641	
642	    private static boolean bool(Object value) {
643	        if (value instanceof Boolean b) {
644	            return b;
645	        }
646	        return value instanceof Number n && n.intValue() != 0;
647	    }
648	
649	    private static LocalDateTime lt(Object value) {
650	        if (value == null) {
651	            return null;
652	        }
653	        return value instanceof Timestamp t ? t.toLocalDateTime() : LocalDateTime.parse(value.toString());
654	    }
655	
656	    private static String requireText(String value, String field) {
657	        if (value == null || value.isBlank()) {
658	            throw new IllegalArgumentException(field + " 不能为空");
659	        }
660	        return value;
661	    }
662	
663	    private static void requireNonNullNonNegative(BigDecimal value, String field) {
664	        if (value == null) {
665	            throw new IllegalArgumentException(field + " 不能为空");
666	        }
667	        if (value.signum() < 0) {
668	            throw new IllegalArgumentException(field + " 不能为负数");
669	        }
670	    }
671	
672	    private static PermitView toPermitView(Map<String, Object> p) {
673	        return new PermitView(
674	                (String) p.get("outlet_code"),
675	                ((Number) p.get("version")).intValue(),
676	                lt(p.get("window_start_utc")).toInstant(ZoneOffset.UTC),
677	                lt(p.get("window_end_utc")).toInstant(ZoneOffset.UTC),
678	                bd(p.get("min_rainfall_mm")),
679	                ((Number) p.get("max_consecutive_hours")).intValue(),
680	                (String) p.get("status"),
681	                lt(p.get("created_at")));
682	    }
683	
684	    private static HourMarkView toHourMarkView(Map<String, Object> h, boolean deduplicated) {
685	        return new HourMarkView(
686	                lt(h.get("hour_utc")).toInstant(ZoneOffset.UTC),
687	                (String) h.get("mark_status"),
688	                permitVersionOf(h),
689	                bd(h.get("rainfall_mm")),
690	                bool(h.get("overflow_flag")),
691	                bd(h.get("avg_value")),
692	                deduplicated);
693	    }
694	
695	    private static ReviewView toReviewView(Map<String, Object> r) {
696	        Object pv = r.get("permit_version");
697	        return new ReviewView(
698	                (String) r.get("outlet_code"),
699	                r.get("day_utc") instanceof java.sql.Date d ? d.toLocalDate()
700	                        : LocalDate.parse(r.get("day_utc").toString()),
701	                pv == null ? null : ((Number) pv).intValue(),
702	                ((Number) r.get("rainfall_version")).intValue(),
703	                bd(r.get("normal_avg")),
704	                ((Number) r.get("normal_count")).intValue(),
705	                bd(r.get("all_avg")),
706	                ((Number) r.get("all_count")).intValue(),
707	                ((Number) r.get("missing_count")).intValue(),
708	                (String) r.get("status"),
709	                lt(r.get("frozen_at")));
710	    }
711	
712	    /** 小时标记判定结果。 */
713	    private record MarkDecision(String markStatus, Integer permitVersion) {
714	    }
715	
716	    /** 双口径均值结果。 */
717	    private record AveragePair(BigDecimal normalAvg, int normalCount, BigDecimal allAvg, int allCount) {
718	    }
719	}
