19	
20	/**
21	 * 雨季溢流证据数据访问层：全部 SQL 参数化；
22	 * 唯一约束承担“排口＋整点去重、排口＋许可版本唯一、排口＋日结唯一、并发占键拒绝”等边界。
23	 */
24	@Repository
25	public class OverflowRepository {
