27	    private final JdbcTemplate jdbc;
28	
29	    public OverflowRepository(JdbcTemplate jdbc) {
30	        this.jdbc = jdbc;
31	    }
32	
33	    // ---------------- 溢流许可版本 ----------------
34	
35	    /** 现行（ACTIVE）许可；无则返回 null。 */
36	    public Map<String, Object> findActivePermit(String code) {
37	        List<Map<String, Object>> rows = jdbc.queryForList(
38	                "SELECT * FROM overflow_permit WHERE outlet_code = ? AND status = 'ACTIVE'", code);
39	        return rows.isEmpty() ? null : rows.get(0);
40	    }
41	
42	    /** 最新版本许可（不论状态）；无则返回 null。 */
43	    public Map<String, Object> findLatestPermit(String code) {
44	        List<Map<String, Object>> rows = jdbc.queryForList(
45	                "SELECT * FROM overflow_permit WHERE outlet_code = ? ORDER BY version DESC LIMIT 1", code);
46	        return rows.isEmpty() ? null : rows.get(0);
47	    }
48	
49	    public List<Map<String, Object>> findPermits(String code) {
50	        return jdbc.queryForList(
51	                "SELECT * FROM overflow_permit WHERE outlet_code = ? ORDER BY version", code);
52	    }
53	
54	    /** 将现行许可置为 SUPERSEDED（新版本取而代之）。 */
55	    public void supersedeActivePermits(String code) {
56	        jdbc.update("UPDATE overflow_permit SET status = 'SUPERSEDED' "
57	                + "WHERE outlet_code = ? AND status = 'ACTIVE'", code);
58	    }
59	
60	    /**
61	     * 写入新许可版本；(outlet_code, version) 唯一约束拒绝并发同版本写入。
62	     * @throws DuplicateKeyException 同版本已存在（并发新增同 expectedVersion）
63	     */
64	    public long insertPermit(String code, int version, LocalDateTime windowStartUtc,
65	                             LocalDateTime windowEndUtc, BigDecimal minRainfallMm,
66	                             int maxConsecutiveHours, LocalDateTime now) {
67	        KeyHolder keyHolder = new GeneratedKeyHolder();
68	        jdbc.update(con -> {
69	            PreparedStatement ps = con.prepareStatement(
70	                    "INSERT INTO overflow_permit(outlet_code, version, window_start_utc, window_end_utc, "
71	                            + "min_rainfall_mm, max_consecutive_hours, status, created_at) "
72	                            + "VALUES (?, ?, ?, ?, ?, ?, 'ACTIVE', ?)",
73	                    Statement.RETURN_GENERATED_KEYS);
74	            ps.setString(1, code);
75	            ps.setInt(2, version);
76	            ps.setTimestamp(3, Timestamp.valueOf(windowStartUtc));
77	            ps.setTimestamp(4, Timestamp.valueOf(windowEndUtc));
78	            ps.setBigDecimal(5, minRainfallMm);
79	            ps.setInt(6, maxConsecutiveHours);
80	            ps.setTimestamp(7, Timestamp.valueOf(now));
81	            return ps;
82	        }, keyHolder);
83	        return keyHolder.getKey().longValue();
84	    }
85	
86	    // ---------------- 溢流小时数据 ----------------
87	
88	    public Map<String, Object> findHour(String code, LocalDateTime hourUtc) {
89	        List<Map<String, Object>> rows = jdbc.queryForList(
90	                "SELECT * FROM overflow_hour WHERE outlet_code = ? AND hour_utc = ?",
91	                code, Timestamp.valueOf(hourUtc));
92	        return rows.isEmpty() ? null : rows.get(0);
93	    }
94	
95	    /**
96	     * 写入小时数据；(outlet_code, hour_utc) 唯一约束去重。
97	     * @return true 新写入；false 该整点已存在
98	     */
99	    public boolean insertHour(String code, LocalDateTime hourUtc, BigDecimal rainfallMm,
100	                              boolean overflowFlag, BigDecimal avgValue, String markStatus,
101	                              Integer permitVersion, LocalDateTime now) {
102	        try {
103	            jdbc.update(con -> {
104	                PreparedStatement ps = con.prepareStatement(
105	                        "INSERT INTO overflow_hour(outlet_code, hour_utc, rainfall_mm, overflow_flag, "
106	                                + "avg_value, mark_status, permit_version, created_at, updated_at) "
107	                                + "VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)");
108	                ps.setString(1, code);
109	                ps.setTimestamp(2, Timestamp.valueOf(hourUtc));
110	                if (rainfallMm == null) {
111	                    ps.setNull(3, Types.DECIMAL);
112	                } else {
113	                    ps.setBigDecimal(3, rainfallMm);
114	                }
115	                ps.setBoolean(4, overflowFlag);
116	                ps.setBigDecimal(5, avgValue);
117	                ps.setString(6, markStatus);
118	                if (permitVersion == null) {
119	                    ps.setNull(7, Types.INTEGER);
120	                } else {
121	                    ps.setInt(7, permitVersion);
122	                }
123	                ps.setTimestamp(8, Timestamp.valueOf(now));
124	                ps.setTimestamp(9, Timestamp.valueOf(now));
125	                return ps;
126	            });
127	            return true;
128	        } catch (DuplicateKeyException e) {
129	            return false;
130	        }
131	    }
132	
133	    public List<Map<String, Object>> findHours(String code) {
134	        return jdbc.queryForList(
135	                "SELECT * FROM overflow_hour WHERE outlet_code = ? ORDER BY hour_utc", code);
136	    }
137	
138	    /** 半开区间 [fromUtc, toUtc) 内的小时数据。 */
139	    public List<Map<String, Object>> findHoursBetween(String code, LocalDateTime fromUtc,
140	                                                      LocalDateTime toUtc) {
141	        return jdbc.queryForList(
142	                "SELECT * FROM overflow_hour WHERE outlet_code = ? AND hour_utc >= ? AND hour_utc < ? "
143	                        + "ORDER BY hour_utc",
144	                code, Timestamp.valueOf(fromUtc), Timestamp.valueOf(toUtc));
145	    }
146	
147	    /** 复核前更正雨量：更新雨量并按当前许可重算标记（同事务）。 */
148	    public void updateHourRainfallAndMark(String code, LocalDateTime hourUtc, BigDecimal rainfallMm,
149	                                         String markStatus, Integer permitVersion, LocalDateTime now) {
150	        jdbc.update(con -> {
151	            PreparedStatement ps = con.prepareStatement(
152	                    "UPDATE overflow_hour SET rainfall_mm = ?, mark_status = ?, permit_version = ?, "
153	                            + "updated_at = ? WHERE outlet_code = ? AND hour_utc = ?");
154	            ps.setBigDecimal(1, rainfallMm);
155	            ps.setString(2, markStatus);
156	            if (permitVersion == null) {
157	                ps.setNull(3, Types.INTEGER);
158	            } else {
159	                ps.setInt(3, permitVersion);
160	            }
161	            ps.setTimestamp(4, Timestamp.valueOf(now));
162	            ps.setString(5, code);
163	            ps.setTimestamp(6, Timestamp.valueOf(hourUtc));
164	            return ps;
165	        });
166	    }
167	
168	    // ---------------- 雨量版本计数 ----------------
169	
170	    /** 当前雨量版本；无记录（尚无小时数据）返回 null。 */
171	    public Integer findRainfallVersion(String code) {
172	        List<Map<String, Object>> rows = jdbc.queryForList(
173	                "SELECT rainfall_version FROM overflow_counter WHERE outlet_code = ?", code);
174	        return rows.isEmpty() ? null : ((Number) rows.get(0).get("rainfall_version")).intValue();
175	    }
176	
177	    /** 首次上报小时数据时初始化雨量版本为 1；并发由主键拒绝后忽略。 */
178	    public void ensureCounter(String code, LocalDateTime now) {
179	        try {
180	            jdbc.update("INSERT INTO overflow_counter(outlet_code, rainfall_version, updated_at) "
181	                    + "VALUES (?, 1, ?)", code, Timestamp.valueOf(now));
182	        } catch (DuplicateKeyException e) {
183	            // 已存在：保持现版本
184	        }
185	    }
186	
187	    /**
188	     * 条件递增雨量版本（乐观并发）：仅当当前版本等于 expected 时置为 expected+1。
189	     * @return 1 成功；0 版本已变化（调用方判 409）
190	     */
191	    public int bumpRainfallVersion(String code, int expected, LocalDateTime now) {
192	        return jdbc.update("UPDATE overflow_counter SET rainfall_version = ?, updated_at = ? "
193	                        + "WHERE outlet_code = ? AND rainfall_version = ?",
194	                expected + 1, Timestamp.valueOf(now), code, expected);
195	    }
196	
197	    // ---------------- 日结复核快照 ----------------
198	
199	    public Map<String, Object> findReview(String code, LocalDate dayUtc) {
