210	    public long insertReview(String code, LocalDate dayUtc, Integer permitVersion, int rainfallVersion,
211	                             BigDecimal normalAvg, int normalCount, BigDecimal allAvg, int allCount,
212	                             int missingCount, String requestId, LocalDateTime frozenAt) {
213	        KeyHolder keyHolder = new GeneratedKeyHolder();
214	        jdbc.update(con -> {
215	            PreparedStatement ps = con.prepareStatement(
216	                    "INSERT INTO overflow_review(outlet_code, day_utc, permit_version, rainfall_version, "
217	                            + "normal_avg, normal_count, all_avg, all_count, missing_count, status, "
218	                            + "frozen_at, request_id) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, 'FROZEN', ?, ?)",
219	                    Statement.RETURN_GENERATED_KEYS);
220	            ps.setString(1, code);
221	            ps.setDate(2, Date.valueOf(dayUtc));
222	            if (permitVersion == null) {
223	                ps.setNull(3, Types.INTEGER);
224	            } else {
225	                ps.setInt(3, permitVersion);
226	            }
227	            ps.setInt(4, rainfallVersion);
228	            if (normalAvg == null) {
229	                ps.setNull(5, Types.DECIMAL);
230	            } else {
231	                ps.setBigDecimal(5, normalAvg);
232	            }
233	            ps.setInt(6, normalCount);
234	            if (allAvg == null) {
235	                ps.setNull(7, Types.DECIMAL);
236	            } else {
237	                ps.setBigDecimal(7, allAvg);
238	            }
239	            ps.setInt(8, allCount);
240	            ps.setInt(9, missingCount);
241	            ps.setTimestamp(10, Timestamp.valueOf(frozenAt));
