243	                ps.setNull(11, Types.VARCHAR);
244	            } else {
245	                ps.setString(11, requestId);
246	            }
247	            return ps;
248	        }, keyHolder);
249	        return keyHolder.getKey().longValue();
250	    }
251	
252	    // ---------------- 独立调差（冻结后） ----------------
253	
