268	                ps.setNull(4, Types.DECIMAL);
269	            } else {
270	                ps.setBigDecimal(4, oldRainfallMm);
271	            }
272	            ps.setBigDecimal(5, newRainfallMm);
273	            ps.setInt(6, rainfallVersion);
274	            if (requestId == null) {
275	                ps.setNull(7, Types.VARCHAR);
276	            } else {
277	                ps.setString(7, requestId);
278	            }
279	            ps.setTimestamp(8, Timestamp.valueOf(now));
