34	/**
35	 * 溢流 H2（MODE=MySQL）真实事务与并发边界测试：
36	 * 同键并发回放唯一受理、同 expectedVersion 并发新增许可/更正雨量唯一受理、
37	 * 日结冻结与小时标记竞争时双口径快照一致。真实线程＋CyclicBarrier 协调，断言最终数据。
38	 */
39	@SpringBootTest
40	class OverflowConcurrencyTest {
41	
42	    private static final String CODE = "OUT-OFC";
43	    private static final LocalDate DAY = LocalDate.of(2026, 9, 26);
44	
45	    @Autowired
46	    private OverflowService service;
47	    @Autowired
48	    private CemsService cemsService;
49	    @Autowired
50	    private CemsClock clock;
51	    @Autowired
52	    private JdbcTemplate jdbc;
53	
54	    @BeforeEach
55	    void setUp() {
56	        CemsTestSupport.clean(jdbc);
57	        clock.reset();
58	        clock.setFixed(CemsTestSupport.T0);
59	        CemsTestSupport.register(cemsService, CODE, "50", "10");
60	    }
61	
62	    private static Instant utc(String text) {
63	        return Instant.parse(text);
64	    }
65	
66	    private static OverflowHourItem item(String hourUtc, String rainfall, boolean overflow, String value) {
67	        return new OverflowHourItem(utc(hourUtc),
68	                rainfall == null ? null : new BigDecimal(rainfall), overflow, new BigDecimal(value));
69	    }
70	
71	    private void permit() {
72	        service.upsertPermit(new PermitUpsertRequest("cc-permit", CODE, 0,
73	                utc("2026-09-26T00:00:00Z"), utc("2026-09-27T00:00:00Z"),
74	                new BigDecimal("5"), 10));
75	    }
76	
77	    @Test
78	    void concurrentSameRequestIdHourReportReplaysSingleResult() throws Exception {
79	        permit();
80	        HourReportRequest req = new HourReportRequest("cc-hours", CODE, List.of(
81	                item("2026-09-26T08:00:00Z", "6", true, "20"),
82	                item("2026-09-26T09:00:00Z", "6", true, "30")));
83	        CyclicBarrier barrier = new CyclicBarrier(2);
84	        ExecutorService pool = Executors.newFixedThreadPool(2);
85	        try {
86	            Future<HourReportResult> f1 = pool.submit(() -> {
87	                barrier.await(10, TimeUnit.SECONDS);
88	                return service.reportHours(req);
89	            });
90	            Future<HourReportResult> f2 = pool.submit(() -> {
91	                barrier.await(10, TimeUnit.SECONDS);
92	                return service.reportHours(req);
93	            });
94	            HourReportResult r1 = f1.get(20, TimeUnit.SECONDS);
95	            HourReportResult r2 = f2.get(20, TimeUnit.SECONDS);
96	            assertEquals(r1.reported(), r2.reported(), "并发同键同参必须回放首次结果");
97	            assertEquals(r1.hours().get(0).markStatus(), r2.hours().get(0).markStatus());
98	        } finally {
99	            pool.shutdownNow();
100	        }
101	        assertEquals(2L, jdbc.queryForObject(
102	                "SELECT COUNT(*) FROM overflow_hour WHERE outlet_code = ?", Long.class, CODE));
103	        assertEquals(1L, jdbc.queryForObject(
104	                "SELECT COUNT(*) FROM idempotent_request WHERE request_id = 'cc-hours'", Long.class));
105	    }
106	
107	    @Test
108	    void concurrentPermitUpsertWithSameExpectedVersionAcceptsOnlyOne() throws Exception {
109	        CyclicBarrier barrier = new CyclicBarrier(2);
110	        ExecutorService pool = Executors.newFixedThreadPool(2);
111	        AtomicInteger accepted = new AtomicInteger();
112	        AtomicInteger rejected = new AtomicInteger();
113	        try {
114	            Runnable task = () -> {
115	                try {
116	                    barrier.await(10, TimeUnit.SECONDS);
117	                } catch (Exception e) {
118	                    throw new IllegalStateException(e);
119	                }
120	                String tag = Thread.currentThread().getName();
121	                try {
122	                    service.upsertPermit(new PermitUpsertRequest("cc-p-" + tag, CODE, 0,
123	                            utc("2026-09-26T00:00:00Z"), utc("2026-09-27T00:00:00Z"),
124	                            new BigDecimal("5"), 10));
125	                    accepted.incrementAndGet();
126	                } catch (ConflictException e) {
127	                    rejected.incrementAndGet();
128	                }
129	            };
130	            Future<?> f1 = pool.submit(task);
131	            Future<?> f2 = pool.submit(task);
132	            f1.get(20, TimeUnit.SECONDS);
133	            f2.get(20, TimeUnit.SECONDS);
134	        } finally {
135	            pool.shutdownNow();
136	        }
137	        assertEquals(1, accepted.get(), "同 expectedVersion 并发新增许可仅一个受理");
138	        assertEquals(1, rejected.get(), "另一并发必须 409 冲突");
139	        assertEquals(1L, jdbc.queryForObject(
140	                "SELECT COUNT(*) FROM overflow_permit WHERE outlet_code = ?", Long.class, CODE));
141	        assertEquals(1, service.getCurrentPermit(CODE).version());
142	    }
143	
144	    @Test
145	    void concurrentRainfallCorrectionsWithSameExpectedVersionAcceptOnlyOne() throws Exception {
146	        permit();
147	        service.reportHours(new HourReportRequest("cc-h", CODE,
148	                List.of(item("2026-09-26T08:00:00Z", null, true, "20"))));
149	        CyclicBarrier barrier = new CyclicBarrier(2);
150	        ExecutorService pool = Executors.newFixedThreadPool(2);
151	        AtomicInteger accepted = new AtomicInteger();
152	        AtomicInteger rejected = new AtomicInteger();
153	        try {
154	            Runnable task = () -> {
155	                try {
156	                    barrier.await(10, TimeUnit.SECONDS);
157	                } catch (Exception e) {
158	                    throw new IllegalStateException(e);
159	                }
160	                String tag = Thread.currentThread().getName();
161	                try {
162	                    RainfallCorrectionResult r = service.correctRainfall(new RainfallCorrectionRequest(
163	                            "cc-c-" + tag, CODE, utc("2026-09-26T08:00:00Z"),
164	                            new BigDecimal("6"), 1));
165	                    assertEquals(2, r.rainfallVersion());
166	                    accepted.incrementAndGet();
167	                } catch (ConflictException e) {
168	                    rejected.incrementAndGet();
169	                }
170	            };
171	            Future<?> f1 = pool.submit(task);
172	            Future<?> f2 = pool.submit(task);
173	            f1.get(20, TimeUnit.SECONDS);
174	            f2.get(20, TimeUnit.SECONDS);
175	        } finally {
176	            pool.shutdownNow();
177	        }
178	        assertEquals(1, accepted.get(), "同雨量版本并发更正仅一个受理");
179	        assertEquals(1, rejected.get());
180	        assertEquals(2, jdbc.queryForObject(
181	                "SELECT rainfall_version FROM overflow_counter WHERE outlet_code = ?",
182	                Integer.class, CODE));
183	        assertEquals("COMPLIANT", jdbc.queryForObject(
184	                "SELECT mark_status FROM overflow_hour WHERE outlet_code = ?", String.class, CODE));
185	    }
186	
187	    @Test
188	    void concurrentFreezeAndHourReportYieldConsistentDualCaliberSnapshot() throws Exception {
189	        permit();
190	        // 预置：08 时普通小时（10）、09 时合规溢流（20）
191	        service.reportHours(new HourReportRequest("cc-pre", CODE, List.of(
192	                item("2026-09-26T08:00:00Z", "1", false, "10"),
193	                item("2026-09-26T09:00:00Z", "6", true, "20"))));
194	
195	        CyclicBarrier barrier = new CyclicBarrier(2);
196	        ExecutorService pool = Executors.newFixedThreadPool(2);
197	        try {
198	            // 竞争：补报 10 时合规溢流（30） vs 当日复核冻结
199	            Future<HourReportResult> reportFuture = pool.submit(() -> {
200	                barrier.await(10, TimeUnit.SECONDS);
201	                return service.reportHours(new HourReportRequest("cc-race-report", CODE,
202	                        List.of(item("2026-09-26T10:00:00Z", "6", true, "30"))));
203	            });
204	            Future<ReviewView> freezeFuture = pool.submit(() -> {
205	                barrier.await(10, TimeUnit.SECONDS);
206	                return service.freezeReview(new ReviewFreezeRequest("cc-race-freeze", CODE, DAY));
207	            });
208	            assertEquals(1, reportFuture.get(20, TimeUnit.SECONDS).reported());
209	            ReviewView review = freezeFuture.get(20, TimeUnit.SECONDS);
210	
211	            // 无论谁先谁后，冻结的双口径结果必须与某一一致快照完全相等（序列化语义）
212	            boolean freezeFirst = review.allCount() == 2 && review.normalCount() == 1
213	                    && review.missingCount() == 22
214	                    && review.allAvg().compareTo(new BigDecimal("15.0000")) == 0
215	                    && review.normalAvg().compareTo(new BigDecimal("10.0000")) == 0;
216	            boolean reportFirst = review.allCount() == 3 && review.normalCount() == 1
217	                    && review.missingCount() == 21
218	                    && review.allAvg().compareTo(new BigDecimal("20.0000")) == 0
219	                    && review.normalAvg().compareTo(new BigDecimal("10.0000")) == 0;
220	            assertTrue(freezeFirst || reportFirst,
221	                    "冻结快照必须等于竞争序列化后的某一一致状态，实际: all=" + review.allAvg()
222	                            + "/" + review.allCount() + " normal=" + review.normalAvg()
223	                            + "/" + review.normalCount() + " missing=" + review.missingCount());
224	            assertEquals(1, review.permitVersion());
225	            assertNotNull(review.frozenAt());
226	        } finally {
227	            pool.shutdownNow();
228	        }
229	        assertEquals(3L, jdbc.queryForObject(
230	                "SELECT COUNT(*) FROM overflow_hour WHERE outlet_code = ?", Long.class, CODE));
231	        assertEquals(1L, jdbc.queryForObject(
232	                "SELECT COUNT(*) FROM overflow_review WHERE outlet_code = ?", Long.class, CODE));
233	    }
234	}
