31	
32	/**
33	 * H2（MODE=MySQL）真实事务与并发边界测试：
34	 * 同键并发重放唯一受理、执行中限排令唯一占槽、生效必有冻结基数的 CHECK 约束、并发解除幂等。
35	 * 使用真实线程与 CyclicBarrier 协调并发，断言最终数据；不靠休眠或打印代替验证。
36	 */
37	@SpringBootTest
38	class CemsConcurrencyTest {
39	
40	    private static final String CODE = "OUT-CC";
41	    private static final LocalDate DAY = LocalDate.of(2026, 9, 26);
42	
43	    @Autowired
44	    private CemsService service;
45	    @Autowired
46	    private CemsClock clock;
47	    @Autowired
48	    private JdbcTemplate jdbc;
49	    @Autowired
50	    private CemsRepository repo;
51	
52	    @BeforeEach
53	    void setUp() {
54	        CemsTestSupport.clean(jdbc);
55	        clock.reset();
56	        clock.setFixed(CemsTestSupport.T0);
57	        CemsTestSupport.register(service, CODE, "50", "10");
58	    }
59	
60	    @Test
61	    void concurrentSameRequestIdProducesSingleResult() throws Exception {
62	        CyclicBarrier barrier = new CyclicBarrier(2);
63	        ExecutorService pool = Executors.newFixedThreadPool(2);
64	        try {
65	            Future<DailyEvalResult> f1 = pool.submit(() -> {
66	                barrier.await(10, TimeUnit.SECONDS);
67	                return service.evaluateDaily(new DailyEvalRequest(
68	                        "idem-concurrent", CODE, DAY, new BigDecimal("60")));
69	            });
70	            Future<DailyEvalResult> f2 = pool.submit(() -> {
71	                barrier.await(10, TimeUnit.SECONDS);
72	                return service.evaluateDaily(new DailyEvalRequest(
73	                        "idem-concurrent", CODE, DAY, new BigDecimal("60")));
74	            });
75	
76	            DailyEvalResult r1 = f1.get(20, TimeUnit.SECONDS);
77	            DailyEvalResult r2 = f2.get(20, TimeUnit.SECONDS);
78	            assertNotNull(r1.markId());
79	            assertEquals(r1.markId(), r2.markId(), "并发同键同参必须回放首次结果");
80	            assertEquals(1L, jdbc.queryForObject(
81	                    "SELECT COUNT(*) FROM exceedance_mark WHERE outlet_code = ? AND mark_type='DAILY_AVG'",
82	                    Long.class, CODE));
83	            assertEquals(1L, jdbc.queryForObject(
84	                    "SELECT COUNT(*) FROM monitor_reading WHERE outlet_code = ? AND period_type='DAY'",
85	                    Long.class, CODE));
86	            assertEquals(1L, jdbc.queryForObject(
87	                    "SELECT COUNT(*) FROM idempotent_request WHERE request_id = 'idem-concurrent'",
88	                    Long.class));
89	        } finally {
90	            pool.shutdownNow();
91	        }
92	    }
93	
94	    @Test
95	    void concurrentOrderInsertionAcceptsOnlyOneForSameSlot() throws Exception {
96	        int threads = 4;
97	        CyclicBarrier barrier = new CyclicBarrier(threads);
98	        ExecutorService pool = Executors.newFixedThreadPool(threads);
99	        AtomicInteger accepted = new AtomicInteger();
100	        AtomicInteger rejected = new AtomicInteger();
101	        try {
102	            for (int i = 0; i < threads; i++) {
103	                final int idx = i;
104	                pool.submit(() -> {
105	                    barrier.await(10, TimeUnit.SECONDS);
106	                    try {
107	                        repo.insertOrder("RO-" + CODE + "-X" + idx, CODE,
108	                                CemsTestSupport.T0.plusHours(idx),
109	                                CemsTestSupport.T0, CemsTestSupport.T0.plusHours(2), CODE);
110	                        accepted.incrementAndGet();
111	                    } catch (DuplicateKeyException e) {
112	                        rejected.incrementAndGet();
113	                    }
114	                    return null;
115	                });
116	            }
117	        } finally {
118	            pool.shutdown();
