            BigDecimal value,
            String submittedBy,
            String reviewedBy,
            String status,
            LocalDateTime createdAt
    ) {
    }

    /**
     * 替代提交/更正结果：frozen=true 表示该日已冻结，本次仅登记独立调差、
     * 不改台账与冻结快照（版本不加）。
     */
    public record SubstituteSubmitResult(
            String requestId,
            String outletCode,
            Instant hourUtc,
            int version,
            String status,
            boolean frozen,
            boolean adjustmentRecorded
    ) {
    }

    /**
     * 替代复核结果：exceedanceMarked=true 表示替代超标已按原阈值追加独立超标来源；
     * frozen=true 表示该日已冻结，本次仅登记独立调差、不改台账。
     */
    public record SubstituteReviewResult(
            String requestId,
            String outletCode,
            Instant hourUtc,
            int version,
            String status,
            boolean exceedanceMarked,
            boolean frozen,
            boolean adjustmentRecorded
    ) {
    }

    /**
     * 有效监测均值：每小时合法机测优先，没有机测才取有效替代，两者不双计；
     * 分母（machineCount+substituteCount）、缺失小时与来源明示；空集合均值 null（无结果而非零）。
     */
    public record EffectiveAveragesView(
            String outletCode,
            Instant fromUtc,
            Instant toUtc,
            long totalSlots,
            int machineCount,
            int substituteCount,
            int missingCount,
            BigDecimal avgValue,
            List<Instant> missingHours
    ) {
    }

    /** 日结冻结槽位视图：冻结时的来源选择与替代版本。 */
    public record FreezeItemView(
            Instant hourUtc,
            String source,
            BigDecimal value,
            Integer substituteVersion
    ) {
    }

    /** 日结冻结快照：冻结当前选择及版本；空集合均值 null。 */
    public record FreezeView(
            String outletCode,
            LocalDate dayUtc,
            BigDecimal avgValue,
            int machineCount,
            int substituteCount,
            int missingCount,
            String status,
            LocalDateTime frozenAt,
            List<FreezeItemView> items
    ) {
    }

    /** 独立调差链条目：冻结后补机测或更正替代只形成调差，不重写冻结均值。 */
    public record AdjustmentView(
            String outletCode,
            LocalDate dayUtc,
            Instant hourUtc,
            String adjustType,
            String oldSource,
            BigDecimal oldValue,
            String newSource,
            BigDecimal newValue,
            Integer substituteVersion,
            String requestId,
            LocalDateTime createdAt
    ) {
    }

    /** 替代超标独立来源视图：只留证不能删除；SUPERSEDED 表示被机测或新版本取代。 */
    public record SubstituteExceedanceView(
            String outletCode,
            Instant hourUtc,
            BigDecimal limitValue,
            BigDecimal actualValue,
            int substituteVersion,
            String status,
            LocalDateTime createdAt
    ) {
    }
}

