        assertThrows(BusinessException.class, () ->
                submit("idem-fail", H08, "8", "RPT-LATE", 0));
        assertEquals(0L, jdbc.queryForObject(
                "SELECT COUNT(*) FROM idempotent_request WHERE request_id = 'idem-fail'", Long.class));
